#!/usr/bin/env python3\n"""CLI to generate ProjectClosureReport.md and PDF."""\nimport os, subprocess\nfrom reporting.services.metric_service import (\n    get_deployment_metrics, get_compliance_audit,\n    get_performance_testing, get_lessons_learned)\nfrom reporting.utils.report_builder import assemble_report\n\ndef main():\n    md_path = os.path.abspath(os.path.join('..', 'reports', 'ProjectClosureReport.md'))\n    pdf_path = os.path.abspath(os.path.join('..', 'reports', 'ProjectClosureReport.pdf'))\n    os.makedirs(os.path.dirname(md_path), exist_ok=True)\n    md_content = assemble_report(\n        get_deployment_metrics(),\n        get_compliance_audit(),\n        get_performance_testing(),\n        get_lessons_learned())\n    with open(md_path, 'w') as f:\n        f.write(md_content)\n    print(f"[CREATED] {md_path}")\n    # Convert markdown to PDF using markdown2 + pdfkit (must be installed)\n    try:\n        import markdown2, pdfkit\n        html = markdown2.markdown(md_content)\n        pdfkit.from_string(html, pdf_path)\n        print(f"[CREATED] {pdf_path}")\n    except Exception as e:\n        print(f"[ERROR] PDF conversion failed: {e}")\n\nif __name__ == '__main__':\n    main()\n